import{_ as t,o as a,c as n,a0 as o}from"./chunks/framework.D4fUSYzX.js";const m=JSON.parse('{"title":"Commands","description":"The bun commands of the repository, the shared control gallery, and the guide screenshots.","frontmatter":{"title":"Commands","description":"The bun commands of the repository, the shared control gallery, and the guide screenshots."},"headers":[],"relativePath":"development/commands.md","filePath":"development/commands.md"}'),r={name:"development/commands.md"};function d(s,e,h,c,i,l){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>bun run dev</code></td><td>Start the control plane in watch mode</td></tr><tr><td><code>bun run test</code></td><td>Run the full test suite</td></tr><tr><td><code>bun run test:changed</code></td><td>Run only the test files the current changes affect</td></tr><tr><td><code>bun run gallery</code></td><td>Run the shared control gallery, using the real modules</td></tr><tr><td><code>bun run lint</code></td><td>Lint and check formatting with Biome</td></tr><tr><td><code>bun run fmt</code></td><td>Lint, format, and fix with Biome</td></tr><tr><td><code>bun run typecheck</code></td><td>Typecheck with TypeScript</td></tr><tr><td><code>bun run screenshots</code></td><td>Regenerate the guide screenshots from fixture state</td></tr></tbody></table><p><code>bun run dev</code> runs the source tree; it reads <code>config/development.toml</code> through <code>--config</code> and watches the tree while it runs. A change to a watched file restarts the control plane inside the same process, so the reload keeps the state file: the run gives the state lease back when the watch signals it, and the next boot takes the lease again. Only the files the run imports are watched, so the state file and the worktrees never trigger a restart.</p><h2 id="scoped-run" tabindex="-1">Scoped run <a class="header-anchor" href="#scoped-run" aria-label="Permalink to &quot;Scoped run&quot;">​</a></h2><p><code>bun run test:changed</code> is the suite, scoped: it runs only the test files that the current changes can affect, so a change to one or two files keeps the run short. It is a speed tool for iteration; the push gate stays the full suite.</p><p>The base ref defaults to <code>origin/main</code> and is overridable with the <code>TEST_CHANGED_BASE</code> environment variable, so work based on another branch scopes against its real base: <code>TEST_CHANGED_BASE=origin/feature bun run test:changed</code>. The run covers committed changes against the base, uncommitted edits, and untracked test files, and it works on a detached head, so a herdr worktree gets the same tool. A clean, up-to-date worktree matches nothing, and the run says so.</p><h2 id="shared-control-gallery" tabindex="-1">Shared control gallery <a class="header-anchor" href="#shared-control-gallery" aria-label="Permalink to &quot;Shared control gallery&quot;">​</a></h2><p><code>bun run gallery</code> opens the shared control gallery: every control the control plane owns, drawn by the production modules and answering the production keys. <code>Tab</code> shows the next example, and each one names its own state - normal and focused, invalid, unavailable, loading, Type-ahead search, and narrow. Pass an example name to land on it: <code>bun run gallery -- fields</code>. The gallery reads no config file, opens no state, and starts no Agent, and the same examples are exercised by <code>bun run test</code>, so a gallery row cannot become an imitation of the control. See <a href="./shared-controls.html">the shared control standard</a>.</p><h2 id="regenerating-the-screenshots" tabindex="-1">Regenerating the screenshots <a class="header-anchor" href="#regenerating-the-screenshots" aria-label="Permalink to &quot;Regenerating the screenshots&quot;">​</a></h2><p><code>bun run screenshots</code> rebuilds the images the <a href="./../operation/main-view.html">operation guide</a> shows: the fixture world, the production binary on a pseudo-terminal, the production keys, and the cell-grid render. The drift test in <code>bun run test</code> reruns the same path and fails when a committed image no longer matches the screen, so a screen change always lands with its image.</p>',10)])])}const g=t(r,[["render",d]]);export{m as __pageData,g as default};
